/* Integrated utilities. The canvas design is authored by Claude. */
const utility=document.createElement('section');utility.id='utilities';utility.className='fl';utility.setAttribute('aria-label','工作工具');document.body.append(utility);
let utilityKind=null,refineAC=null,refineResult=null,originalPrompt='',utilityEpoch=0;
const baseRenderTop=renderTop;renderTop=function(){baseRenderTop();const gb=$('#gb');if(!gb.querySelector('[data-util]'))gb.insertAdjacentHTML('afterbegin',`<button data-util="auth" aria-label="自动化授权" title="Auth Relay">${icon('settings')}授权</button><button data-util="prompt" aria-label="Prompt 优化" title="Snapper Assist">${icon('sparkles')}Prompt</button>`)};
CAT.push(['auth.open','查看自动化授权与原生控制入口',''],['prompt.open','打开 Snapper Assist 推敲 Prompt','text?'],['prompt.refine','按原文选 Skill 并优化（联网）','text'],['prompt.apply','将已优化内容放入当前项目草稿，不发送','projectId']);
ACT['auth.open']=()=>{openUtility('auth');return'已打开现有授权状态'};
ACT['prompt.open']=a=>{openUtility('prompt',a.text);return'已打开 Prompt 优化'};
ACT['prompt.refine']=a=>{openUtility('prompt',a.text);runRefinement();return'已开始理解原文与选择 Skill，可随时停止'};
ACT['prompt.apply']=a=>{const p=rp(a.projectId);if(!refineResult?.text)throw'先完成一条 Prompt 优化';pushUndo();p.ui.composerDraft=refineResult.text;save();return'已放入「'+p.name+'」草稿，尚未发送'};
function openUtility(kind,text){if(text!==undefined)originalPrompt=text;utilityKind=kind;utilityEpoch++;utility.classList.add('o');utility.innerHTML=`<h3>${icon(kind==='auth'?'settings':'sparkles')}${kind==='auth'?'自动化授权':'Snapper Assist'}<button class="x" data-util-close aria-label="关闭工具">${icon('close')}</button></h3>`+(kind==='auth'?`<p class="lab">连接现有会话，查看接力状态与范围。</p><div id="auth-state" role="status">读取现有状态…</div><div class="row"><button data-auth-refresh>刷新状态</button><button data-native="auth">打开原生控制面板 ${icon('enter',14)}</button></div><p class="lab">在原生面板中开启、暂停或调整范围，保留已有账号连接。</p>`:`<p class="lab">先理解这条请求，再选择和读取相关 Skill 推敲；保留你的语气与明确限制。</p><div class="utility-grid"><div><label for="prompt-original">原始想法</label><textarea id="prompt-original" placeholder="直接写你原本想说的话…">${esc(originalPrompt)}</textarea><div class="row"><button data-refine-start>${icon('sparkles')}开始推敲</button><button data-refine-stop ${refineAC?'':'hidden'}>${icon('stop')}停止</button><button data-native="snapper" title="选中文字旁的桌面浮条">桌面浮条 ${icon('enter',14)}</button></div><p id="refine-phase" class="lab" role="status">主动点击后调用 Claude · 不会自动执行原任务</p></div><div><label for="prompt-result">优化后的请求</label><textarea id="prompt-result" placeholder="这里呈现本条请求的推敲结果，可继续手改">${esc(refineResult?.text||'')}</textarea><div class="row"><button data-prompt-copy>复制</button><button data-prompt-apply>放入项目草稿</button><button data-prompt-apply-goal>设为项目目标</button><button data-prompt-restore>恢复原文</button></div></div></div><div id="refine-evidence"></div>`);
 if(kind==='auth')refreshAuth();else{if(refineResult)showRefineEvidence();$('#prompt-original').focus()}}
async function refreshAuth(){const el=$('#auth-state');if(!el)return;try{const r=await fetch('/api/studio/auth'),s=await r.json();if(!r.ok)throw new Error(s.error||'读取失败');if(!$('#auth-state'))return;$('#auth-state').innerHTML=`<div class="ac"><b>${s.connected?(s.enabled?'● 现有授权已开启':'‖ 现有授权已暂停'):'○ 原生服务未连接'}</b><p>${s.connected?`当前活动任务 ${s.activeTasks} · 短信通道 ${esc(({idle:"待命",waiting:"等待新短信",relayed:"已接力",expired:"本轮已过期"})[s.smsPhase]||"已连接")}`:'可以打开已安装的 Auth Relay 查看或连接。'}</p>${s.scope?.length?`<span class="lab">当前范围：${s.scope.map(esc).join('、')}</span>`:''}</div>`}catch(e){if($('#auth-state'))$('#auth-state').textContent='无法读取状态：'+e.message}}
async function runRefinement(){if(refineAC)return hint('正在推敲，可先停止');const text=$('#prompt-original')?.value.trim();if(!text)return hint('先写下原始想法');originalPrompt=text;const epoch=utilityEpoch,ac=refineAC=new AbortController();$('#refine-phase').textContent='正在理解原文 → 按语义选择 Skill → 读取正文深化…';$('[data-refine-stop]').hidden=false;$('[data-refine-start]').disabled=true;
 try{const r=await fetch('/api/studio/refine',{method:'POST',headers:{'Content-Type':'application/json'},signal:ac.signal,body:JSON.stringify({text,libraryBindings:((P(state.room)||P(state.sel))?.skillRefs||[]).filter(r=>r.mode==='guide').map(({id,bodyHash})=>({id,bodyHash}))})}),d=await r.json();if(!r.ok)throw new Error(d.error||'优化未完成');if(ac.signal.aborted)return;refineResult=d;if(epoch!==utilityEpoch||utilityKind!=='prompt')return;$('#prompt-result').value=d.text;$('#refine-phase').textContent='已按本条请求完成推敲 · 可检查、手改或恢复原文';showRefineEvidence()}
 catch(e){if(epoch===utilityEpoch&&$('#refine-phase'))$('#refine-phase').textContent=e.name==='AbortError'?'已停止，原文保留':'本次未完成：'+e.message}
 finally{if(refineAC===ac)refineAC=null;if(epoch===utilityEpoch&&$('[data-refine-stop]')){$('[data-refine-stop]').hidden=true;$('[data-refine-start]').disabled=false}}}
function showRefineEvidence(){const el=$('#refine-evidence'),d=refineResult;if(!el||!d)return;el.innerHTML=`<div class="lab">理解为：${esc(d.intent)}</div><div class="row">${d.skills?.map(s=>`<div class="ac"><b>${esc(s.title)}</b><div>${esc(s.reason)}</div><div class="lab">${esc(d.application?.find(a=>a.id===s.id)?.used||'本次选择并读取')}</div></div>`).join('')||'<div class="lab">本条请求无需额外 Skill。</div>'}</div>${d.changes?.length?`<details><summary>本次调整</summary>${d.changes.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}${d.questions?.length?`<div class="ac">关键缺口：${d.questions.map(esc).join('；')}</div>`:''}`}
document.addEventListener('input',e=>{if(e.target.id==='prompt-original')originalPrompt=e.target.value;if(e.target.id==='prompt-result'&&refineResult)refineResult.text=e.target.value});
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;
 if(t.dataset.optGoal){const p=P(t.dataset.optGoal);openUtility("prompt",p?.summary||p?.name||"");return}if(t.dataset.util){const txt=t.closest("#cmp")?($("#rin")?.value||P(state.room)?.summary||""):(t.closest("#pan")?(P(panId)?.summary||P(panId)?.name||""):undefined);openUtility(t.dataset.util,txt);return}else if(t.hasAttribute('data-util-close')){utility.classList.remove('o');utilityKind=null;utilityEpoch++;refineAC?.abort()}
 else if(t.hasAttribute('data-auth-refresh'))refreshAuth();else if(t.hasAttribute('data-refine-start'))runRefinement();else if(t.hasAttribute('data-refine-stop'))refineAC?.abort();
 else if(t.hasAttribute('data-prompt-restore')){$('#prompt-result').value=originalPrompt;if(refineResult)refineResult.text=originalPrompt}
 else if(t.hasAttribute('data-prompt-copy')){try{await navigator.clipboard.writeText($('#prompt-result').value);hint('已复制')}catch{hint('复制未完成，请选中结果复制')}}
 else if(t.hasAttribute('data-prompt-apply')){const p=P(state.room)||P(state.sel);if(!p)return hint('先在画板选中一个项目');act('prompt.apply',{projectId:p.id})}else if(t.hasAttribute('data-prompt-apply-goal')){const p=P(state.room)||P(state.sel)||P(panId);if(!p)return hint('先在画板选中一个项目');const txt=refineResult?.text||$('#prompt-result')?.value?.trim();if(!txt)return hint('先完成一条 Prompt 优化');pushUndo();p.summary=txt;save();renderAll();if(panK==='proj'&&panId===p.id)renderPan();hint('已设为「'+p.name+'」的目标')}
 else if(t.dataset.native){try{const r=await fetch('/api/studio/open',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app:t.dataset.native})}),d=await r.json();hint(r.ok?'已打开原生应用':d.error)}catch(e){hint('打开未完成：'+e.message)}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&utility.classList.contains('o')){utility.classList.remove('o');utilityKind=null;utilityEpoch++;refineAC?.abort();e.stopImmediatePropagation()}},true);

